#!/usr/bin/env node
/**
 * Guardrail for public/datacenters.json.
 *
 * The dataset is regenerated by scripts/enrich_datacenters.py and edited by
 * hand, and a bad run degrades the map quietly — pins drift into the ocean, or
 * coverage silently halves — rather than throwing. This asserts the invariants
 * that matter and fails CI when one breaks.
 *
 * Run: node scripts/validate-dataset.mjs
 */

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const DATA = join(ROOT, 'public', 'datacenters.json');

/**
 * Floors, not exact counts — the dataset is expected to grow. They exist to
 * catch collapse (a geocoding regression, a truncated write), not drift.
 */
const MIN_ROWS = 18_000;
const MIN_LOCATED = 17_000;
const MIN_PRECISE = 15_500; // site + postal + city
const MIN_COUNTRIES = 150;

const PRECISIONS = new Set(['site', 'postal', 'city', 'state', 'country']);
const PRECISE = new Set(['site', 'postal', 'city']);

/**
 * Upstream ships a tail of records that are empty beyond a name — no company,
 * no address, no coordinates. They are carried rather than dropped so the
 * inventory count still matches the source, but they cannot be repaired from
 * the data we have. These ceilings tolerate the known tail while still failing
 * if it grows, which would mean a regression rather than upstream noise.
 */
const MAX_MISSING_COMPANY = 30;
const MAX_MISSING_COUNTRY = 200;

/**
 * A ceiling as well as a floor. The enrichment script merges new upstream rows
 * into the committed file, and a merge key that is not stable across runs
 * silently re-adds hundreds of rows every time — which is exactly what
 * happened: the file grew 18,188 -> 18,549 on a single re-run, stacking
 * duplicate pins on the same coordinate and inflating every per-country count.
 * A floor alone cannot see that.
 */
const MAX_ROWS = 19_500;

/**
 * Upstream ATLAS itself lists 13 facilities twice (same name, operator and
 * address). They are carried rather than silently dropped, so the ceiling
 * tolerates the known set while still catching a merge that starts
 * manufacturing new ones.
 */
const MAX_DUPLICATES = 20;

const errors = [];
const fail = (msg) => errors.push(msg);

let rows;
try {
  rows = JSON.parse(readFileSync(DATA, 'utf8'));
} catch (err) {
  console.error(`Cannot read ${DATA}: ${err.message}`);
  process.exit(1);
}

if (!Array.isArray(rows)) {
  console.error('Expected a top-level JSON array.');
  process.exit(1);
}

let located = 0;
let precise = 0;
const countries = new Set();
// Only rows that actually render can pollute the map's country list.
const renderedCountries = new Set();
const byPrecision = new Map();
let sampleBadCoord = null;
let sampleBadPrecision = null;
let missingCountry = 0;
let missingCompany = 0;
// Identity as the enrichment script defines it. Duplicates here mean the same
// facility was merged in more than once.
const seen = new Set();
const duplicates = new Set();

for (let i = 0; i < rows.length; i++) {
  const r = rows[i];
  if (!r || typeof r !== 'object') {
    fail(`row ${i} is not an object`);
    continue;
  }
  if (!r.name) fail(`row ${i} has no name`);
  const id = [r.name, r.company, r.address || r.city].join('|').toLowerCase();
  if (seen.has(id)) duplicates.add(id);
  else seen.add(id);
  if (!r.company) missingCompany++;
  if (!r.country) missingCountry++;
  else countries.add(r.country);

  const c = r.city_coords;
  if (c !== undefined) {
    const ok =
      Array.isArray(c) &&
      c.length === 2 &&
      Number.isFinite(c[0]) &&
      Number.isFinite(c[1]) &&
      c[0] >= -90 &&
      c[0] <= 90 &&
      c[1] >= -180 &&
      c[1] <= 180 &&
      // Null Island is a geocoder failure, never a real facility.
      !(Math.abs(c[0]) < 0.01 && Math.abs(c[1]) < 0.01);
    if (!ok) {
      if (!sampleBadCoord) sampleBadCoord = `row ${i} (${r.name}): ${JSON.stringify(c)}`;
      continue;
    }
    located++;
    if (r.country) renderedCountries.add(r.country);

    // A located row must say how it was located, or the UI cannot be honest
    // about its accuracy and the LOD ranking loses its main signal.
    if (!PRECISIONS.has(r.precision)) {
      if (!sampleBadPrecision)
        sampleBadPrecision = `row ${i} (${r.name}): precision=${JSON.stringify(r.precision)}`;
    } else {
      byPrecision.set(r.precision, (byPrecision.get(r.precision) ?? 0) + 1);
      if (PRECISE.has(r.precision)) precise++;
    }
  }
}

if (sampleBadCoord) fail(`invalid city_coords, e.g. ${sampleBadCoord}`);
if (sampleBadPrecision) fail(`located row without valid precision, e.g. ${sampleBadPrecision}`);
if (missingCompany > MAX_MISSING_COMPANY)
  fail(`${missingCompany} rows missing company, ceiling is ${MAX_MISSING_COMPANY}`);
if (missingCountry > MAX_MISSING_COUNTRY)
  fail(`${missingCountry} rows missing country, ceiling is ${MAX_MISSING_COUNTRY}`);

// The country field is what the globe keys its choropleth off, so a blow-up
// here means phantom countries in the UI (it was 344 before repair).
const MAX_COUNTRIES_RENDERED = 200;
if (renderedCountries.size > MAX_COUNTRIES_RENDERED)
  fail(
    `${renderedCountries.size} distinct countries among rendered rows, ` +
      `ceiling is ${MAX_COUNTRIES_RENDERED} — country field likely polluted`
  );
if (rows.length < MIN_ROWS) fail(`only ${rows.length} rows, expected >= ${MIN_ROWS}`);
if (rows.length > MAX_ROWS)
  fail(`${rows.length} rows exceeds ceiling ${MAX_ROWS} — likely duplicated on merge`);
if (duplicates.size > MAX_DUPLICATES)
  fail(
    `${duplicates.size} duplicated identities (ceiling ${MAX_DUPLICATES}), ` +
      `e.g. ${[...duplicates][0]} — the enrichment merge key is probably ` +
      `unstable across runs`
  );
if (located < MIN_LOCATED) fail(`only ${located} located rows, expected >= ${MIN_LOCATED}`);
if (precise < MIN_PRECISE) fail(`only ${precise} precise rows, expected >= ${MIN_PRECISE}`);
if (countries.size < MIN_COUNTRIES)
  fail(`only ${countries.size} countries, expected >= ${MIN_COUNTRIES}`);

const pct = (n) => `${((100 * n) / rows.length).toFixed(1)}%`;
console.log(`datacenters.json — ${rows.length.toLocaleString()} rows`);
for (const p of ['site', 'postal', 'city', 'state', 'country']) {
  const n = byPrecision.get(p) ?? 0;
  if (n) console.log(`  ${p.padEnd(8)} ${String(n).padStart(6)}  ${pct(n)}`);
}
console.log(`  located  ${String(located).padStart(6)}  ${pct(located)}`);
console.log(`  precise  ${String(precise).padStart(6)}  ${pct(precise)}`);
console.log(`  ${renderedCountries.size} distinct countries among rendered rows`);
console.log(`  ${missingCompany} rows without company, ${missingCountry} without country`);
console.log(`  ${duplicates.size} duplicated identities`);

if (errors.length) {
  console.error(`\n${errors.length} problem(s):`);
  for (const e of errors) console.error(`  ✗ ${e}`);
  process.exit(1);
}
console.log('\nAll dataset invariants hold.');
